\set ON_ERROR_STOP on
DO $$ BEGIN
 IF (SELECT count(*) FROM public.purchases WHERE pharmacy_id='a2000000-0000-4000-8000-000000000001')<>1 THEN RAISE EXCEPTION 'CONCURRENCY_PURCHASE_COUNT';END IF;
 IF (SELECT count(*) FROM public.purchase_items pi JOIN public.purchases p ON p.id=pi.purchase_id WHERE p.pharmacy_id='a2000000-0000-4000-8000-000000000001')<>1 THEN RAISE EXCEPTION 'CONCURRENCY_ITEM_COUNT';END IF;
 IF (SELECT count(*) FROM public.inventory_batches WHERE pharmacy_id='a2000000-0000-4000-8000-000000000001' AND quantity=5)<>1 THEN RAISE EXCEPTION 'CONCURRENCY_STOCK_EFFECT';END IF;
 IF (SELECT count(*) FROM public.stock_ledger WHERE pharmacy_id='a2000000-0000-4000-8000-000000000001' AND quantity_delta=5)<>1 THEN RAISE EXCEPTION 'CONCURRENCY_LEDGER_EFFECT';END IF;
 IF (SELECT count(*) FROM public.audit_logs WHERE pharmacy_id='a2000000-0000-4000-8000-000000000001' AND action='STOCK_INTAKE_RECEIVED')<>1 THEN RAISE EXCEPTION 'CONCURRENCY_AUDIT_EFFECT';END IF;
 IF (SELECT count(*) FROM public.entitlement_committed_operations_v1 WHERE pharmacy_id='a2000000-0000-4000-8000-000000000001' AND operation_kind='INVENTORY_INTAKE')<>1 THEN RAISE EXCEPTION 'CONCURRENCY_EVIDENCE_COUNT';END IF;
END $$;
SELECT 'PF_COUNT|concurrency|purchase=1|item=1|stock=5|ledger=1|audit=1|evidence=1';
